import{_ as a,o,c as d,ag as t}from"./chunks/framework.C0B4Gdhp.js";const u=JSON.parse('{"title":"Web で開く","description":"","frontmatter":{},"headers":[],"relativePath":"guide/web.md","filePath":"guide/web.md","lastUpdated":1789914287000}'),i={name:"guide/web.md"};function c(s,e,p,n,r,l){return o(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="web-で開く" tabindex="-1">Web で開く <a class="header-anchor" href="#web-で開く" aria-label="Permalink to &quot;Web で開く&quot;">​</a></h1><p>Web は部分対応です。Unity 6000.6.2f1、パッケージ 8.0.0-pre.1 です。実機センサーの課題の代用にはなりません。</p><h2 id="ビルドと開き方" tabindex="-1">ビルドと開き方 <a class="header-anchor" href="#ビルドと開き方" aria-label="Permalink to &quot;ビルドと開き方&quot;">​</a></h2><p>通常のアプリは、ビルド設定で Web を選び、<code>Assets/Game.unity</code> をビルドします。出力先は、ビルドのときに指定したフォルダです。診断アプリは <code>bash scripts/unity-validate.sh web</code> です。出力は <code>Build/Validation/Web</code> です。</p><p>ビルドしたフォルダは HTTP サーバで開きます。ローカルのプレビュー例です。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http.server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bind</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Build/Validation/Web</span></span></code></pre></div><p>このコマンドは、その PC を使う本人だけが開くためのものです。外部公開は別です。ブラウザで <code>http://127.0.0.1:8000</code> を開きます。</p><p>カメラなど権限付き機能には、HTTPS か localhost の安全なコンテキストが要ります。通信は接続先の CORS 許可も要ります。無いと取れません。</p><h2 id="テンプレート" tabindex="-1">テンプレート <a class="header-anchor" href="#テンプレート" aria-label="Permalink to &quot;テンプレート&quot;">​</a></h2><p>標準テンプレートは <code>Assets/WebGLTemplates/GameCanvas/index.html</code> です。画面サイズに合わせ、<code>autoSyncPersistentDataPath</code> は真です。既定の Player Settings の WebGL テンプレートは <code>PROJECT:GameCanvas</code> です。</p><h2 id="実装と確認" tabindex="-1">実装と確認 <a class="header-anchor" href="#実装と確認" aria-label="Permalink to &quot;実装と確認&quot;">​</a></h2><p>実装があることと、確認した範囲は別です。位置情報と加速度は Web では未対応で、<code>Start</code> すると <code>Unsupported</code> です。カメラの入口は Web にもあります。画面を押してから <code>Start</code> します。ページが隠れると中断になり、カメラは止まります。戻っても自動では再開しないので、もう一度 <code>Start</code> してください。許可待ちの既定は 30 秒で、変更できます。操作がそれを超えると <code>TimedOut</code> になります。許可が済めば、もう一度 <code>Start</code> して再試行できます。</p><p>確認した環境は、localhost 上の Codex 内蔵ブラウザの Chromium 153、macOS 27 の Safari 27、iOS 26.4 Simulator の Safari 26.4、Pixel 9a（Android 17）の Chrome 145.0.7632.218 です。</p><p>Codex 内蔵ブラウザの Chromium 153 では、画像と日本語、マウスの <code>gc.Drag</code>、Space の Down と Up、HTTP GET の本文と画像、404、Cancel、Timeout、保存と再読み込みを確認しました。画面をクリックしたあと、<code>gc.IsPlayingSound(GcSoundTrack.SE)</code> は真でした。耳では再生を確認していません。カメラは許可待ちから <code>NotGranted</code> へ完了し、<code>Stop</code> で <code>Stopped</code> までを確認しました。実映像は未確認です。</p><p>Safari 27 では、画像と日本語、手操作の <code>gc.Drag</code>、Space の Down と Up、HTTP GET の本文と画像、404、Cancel、Timeout、保存と再読み込みを確認しました。音は Chromium 153 の結果だけです。別タブへ切り替えると <code>lifecycle.pause</code>、元のタブへ戻ると <code>lifecycle.resume</code> になり、カメラは <code>Stopped</code> でした。保存は 3 から 4 へ増え、通信診断も成功しました。カメラの実映像は見ていません。</p><p>iOS 26.4 Simulator の Safari 26.4 では、画像と日本語、HTTP GET の本文と画像、404、Cancel、Timeout を確認しました。シミュレータでマウスを動かし、青い矩形のドラッグを確認しました。Begin と End の座標は違っていました。複数指は未確認です。再読み込み後、保存は 1 から 2 へ増え、通信診断も成功しました。ホームへ移動すると <code>lifecycle.pause</code>、Safari に戻ると <code>lifecycle.resume</code> になり、カメラは <code>Stopped</code> でした。実映像はシミュレータでは見ていません。</p><p>Pixel 9a の Chrome では、localhost で画像と日本語、タッチのドラッグ、HTTP GET の本文と画像、404、Cancel、Timeout を確認しました。保存は増え、再読み込み後も残っていました。加速度は <code>Unsupported</code> でした。音ボタンのあと、<code>gc.IsPlayingSound</code> は真でした。耳では再生を確認していません。カメラは、ブラウザの許可と Android の許可を出したあと、実フレームが <code>Running</code> になりました。写っているものの上下と向きは見ていません。許可の操作が既定の待ちを超えた初回は <code>TimedOut</code> で終わり、許可のあとでもう一度 <code>Start</code> して再試行できました。ブラウザをバックグラウンドへ移すと一時停止し、戻ったあとは <code>Stopped</code> で、許可は <code>Granted</code> のままでした。開始操作でもう一度始まりました。</p><p>通常のデスクトップ Chrome と、HTTPS での公開は未確認です。背景からの復帰は、アプリ内ブラウザでは未確認です。確認した環境での成功を、未確認のブラウザの保証にはしません。</p>',18)])])}const m=a(i,[["render",c]]);export{u as __pageData,m as default};
